package jp.terada.midnitelogger; import android.content.*; import android.graphics.*; import android.view.*; import java.util.*;
public class ChartView extends View{private List<float[]> p=new ArrayList<float[]>();private String title="";public ChartView(Context c){super(c);}public void set(List<float[]>x,String t){p=x;title=t;invalidate();}protected void onDraw(Canvas c){super.onDraw(c);Paint a=new Paint(1);a.setColor(Color.DKGRAY);a.setTextSize(28);c.drawText(title,12,30,a);if(p.size()<2){c.drawText("表示データがありません",30,100,a);return;}float min=Float.MAX_VALUE,max=-Float.MAX_VALUE;for(float[]q:p){min=Math.min(min,q[1]);max=Math.max(max,q[1]);}if(max==min){max+=1;min-=1;}float l=55,t=48,r=getWidth()-12,b=getHeight()-38;a.setStyle(Paint.Style.STROKE);a.setColor(Color.LTGRAY);c.drawRect(l,t,r,b,a);Path path=new Path();for(int i=0;i<p.size();i++){float x=l+(r-l)*i/(p.size()-1f),y=b-(b-t)*(p.get(i)[1]-min)/(max-min);if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}a.setColor(Color.BLUE);a.setStrokeWidth(3);c.drawPath(path,a);a.setStyle(Paint.Style.FILL);a.setColor(Color.DKGRAY);a.setTextSize(20);c.drawText(String.format(Locale.US,"%.2f",max),2,t+10,a);c.drawText(String.format(Locale.US,"%.2f",min),2,b,a);}}
